module tb_TopModule;
    reg clk;
    reg areset;
    reg bump_left;
    reg bump_right;
    wire walk_left;
    wire walk_right;

    TopModule dut (
        .clk(clk),
        .areset(areset),
        .bump_left(bump_left),
        .bump_right(bump_right),
        .walk_left(walk_left),
        .walk_right(walk_right)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 1;
        bump_left = 0;
        bump_right = 0;

        #12;
        areset = 0;

        // Check initial state after reset: walk_left=1, walk_right=0
        if (walk_left !== 1 || walk_right !== 0) begin
            $display("SELFTEST FAIL: Reset state incorrect. walk_left=%b, walk_right=%b", walk_left, walk_right);
            $finish;
        end

        // Test 1: bump_left while walking left -> should switch to walking right
        @(posedge clk);
        bump_left = 1;
        @(posedge clk);
        bump_left = 0;

        if (walk_left !== 0 || walk_right !== 1) begin
            $display("SELFTEST FAIL: After bump_left, expected walk_right=1, got walk_left=%b, walk_right=%b", walk_left, walk_right);
            $finish;
        end

        // Test 2: bump_right while walking right -> should switch to walking left
        @(posedge clk);
        bump_right = 1;
        @(posedge clk);
        bump_right = 0;

        if (walk_left !== 1 || walk_right !== 0) begin
            $display("SELFTEST FAIL: After bump_right, expected walk_left=1, got walk_left=%b, walk_right=%b", walk_left, walk_right);
            $finish;
        end

        // Test 3: bump_right while walking left -> should stay walking left
        @(posedge clk);
        bump_right = 1;
        @(posedge clk);
        bump_right = 0;

        if (walk_left !== 1 || walk_right !== 0) begin
            $display("SELFTEST FAIL: bump_right while walking left changed state unexpectedly");
            $finish;
        end

        // Test 4: both bumps while walking left -> should switch to walking right
        @(posedge clk);
        bump_left = 1;
        bump_right = 1;
        @(posedge clk);
        bump_left = 0;
        bump_right = 0;

        if (walk_left !== 0 || walk_right !== 1) begin
            $display("SELFTEST FAIL: both bumps while walking left failed to switch direction");
            $finish;
        end

        // Test 5: asynchronous reset test
        @(posedge clk);
        areset = 1;
        #2;
        if (walk_left !== 1 || walk_right !== 0) begin
            $display("SELFTEST FAIL: Asynchronous reset failed");
            $finish;
        end
        areset = 0;

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

